---@class RechargeRewardData
RechargeRewardData = class("RechargeRewardData")
function RechargeRewardData:initialize()
    ---獎品
    ---@type table<number,number>
    self.rewardPropIdTable = {}
    ---@type table<number,number>
    self.rewardPropNumTable = {}
    self.sumVal = 0---累计值
    self.CurrencyType = ""---货币类型
    self.state = RechargeRewardType.UnFinished---0不可领取 1可领取 2已领取
end

---@param config act_sumcharge_config_cell
function RechargeRewardData:SetDataByConfig(config)
    local a,b = math.modf(config.sumval)
    self.sumVal = b>0 and config.sumval or a
    self.CurrencyType = config.CurrencyType
    local propIds = stringSplit(config.propsids,":")
    local propNums = stringSplit(config.propsnums,":")
    for i = 1, #propIds do
        table.insert(self.rewardPropIdTable,tonumber(propIds[i]))
        table.insert(self.rewardPropNumTable,tonumber(propNums[i]))
    end
end

---@param msg SC_ActWordExch
function RechargeRewardData:SetDataByMsg(msg)
end

---@return number,number
function RechargeRewardData:GetPropByIndex(index)
    return  self.rewardPropIdTable[index],self.rewardPropNumTable[index]
end


