    local id = actId and actId or self.curConfig.actId
    return  self.RechargeRewardActDataTab[id]
end

function RechargeRewardManager:InitRechargeRewardData(actId)
    self.RechargeRewardDataTab[actId]={}
    ---@type act_bussiness_config_cell
    local _data = CommonHelper:GetTableDataByID(ConfigNames.act_bussiness_config,actId)
    self.curConfig.sumType=tonumber(_data.itemids)
    self:InitActRechargeRewardTable(self.RechargeRewardDataTab[actId])
end

---@return table<number,RechargeRewardData>
function RechargeRewardManager:GetRechargeRewardDataTable(actId)
    local id=actId and actId or self.curConfig.actId
    return self.RechargeRewardDataTab[id]
end

---@return RechargeRewardData
function RechargeRewardManager:GetRechargeRewardDataByIndex(index,actId)
    actId=actId==nil and self.curConfig.actId or actId
    if self.RechargeRewardDataTab[actId] and self.RechargeRewardDataTab[actId][index] then
        return self.RechargeRewardDataTab[actId][index]
    end
end

---@return RechargeRewardData
function RechargeRewardManager:GetRechargeRewardDataByConfigIndex(configIndex,actId)
    actId=actId==nil and self.curConfig.actId or actId
    for i = 1, #self.RechargeRewardDataTab[actId] do
        if self.RechargeRewardDataTab[actId][i].configIndex == configIndex then
            return self.RechargeRewardDataTab[actId][i]
        end
    end
    return nil
end

function RechargeRewardManager:InitActRechargeRewardTable(RechargeRewardTable)
    ---@type act_sumcharge_config
    local tab = ClientDataManager:Get():GetDataTable(ConfigNames.act_sumcharge_config)
    ---@type table<act_sumcharge_config_cell>
    local configTab = tab.GetConfigDataBySumType(self.curConfig.sumType)
    for i = 1, #configTab  do --#configTab
        local data = RechargeRewardData()
        data:SetDataByConfig(configTab[i])
        table.insert(RechargeRewardTable,data)
    end
end

---@param msg SC_ActSumCharge
function RechargeRewardManager:SetInfoDataByActSumCharge(msg)
    self:GetActData(msg.actId):SetDataByMsg(msg)
    ---@type table<number,RechargeRewardData>
    local table = self:GetRechargeRewardDataTable(msg.actId)
    local redPointID = self:GetActData(msg.actId).sumType<1000 and RedPointID.S_ActSingleDayRechargerReward or RedPointID.S_ActRechargerReward
    local redPointActiveOriginal =  RedPointManager:Get():GetValue(redPointID)
    local redPointActive = self:GetActData(msg.actId).boxGift == 0
    for i = 1, #msg.giftFlags do
        if table[i] then
            table[i].state = msg.giftFlags[i]
            if table[i].state ==RechargeRewardType.Unclaimed then
                redPointActive=true
            end
        end
    end
    if redPointActiveOriginal and redPointActive==false then
        RedPointManager:Get():UpdateValue(redPointID,redPointActive)
        UINotify:Get():SendNotification(UINotifyEvent.CommonAct_RefreshChooseBtn)
    end
end

function RechargeRewardManager:Clear()
    ---@type  table<number,table<number,RechargeRewardData>>
    self.RechargeRewardDataTab = {}
    ---@type  table<number,RechargeRewardActData>
    self.RechargeRewardActDataTab = {}
    ---@type  RechargeRewardActData
    self.curInfoData =nil
end

